out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cases_s1.jsonl")
if __name__ == "__main__":
    ids = [c["id"] for c in S]; assert len(ids) == len(set(ids))
    with open(out, "w", encoding="utf-8") as f:
        for c in S: f.write(json.dumps(c, ensure_ascii=False) + "\n")
    print(len(S), "cases written")
